#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, NR, NQ, NP, ...)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout   = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout  = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                 // sum[p]

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

void init_array(auto A, auto C4) {
	using namespace noarr;

	// Cache lengths once; they are the same for all elements
	const std::size_t np_len_A  = A  | get_length<'p'>();
	const std::size_t np_len_C4 = C4 | get_length<'p'>();

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);

		A[state] = static_cast<num_t>((r * q + p) % np_len_A)
			/ static_cast<num_t>(np_len_A);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);

		C4[state] = static_cast<num_t>((s * p) % np_len_C4)
			/ static_cast<num_t>(np_len_C4);
	});
}

// ---------------------------------------------------------------------------
// Computation kernel
//
// Original C kernel:
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// Optimized Noarr version:
//
// 1) For each (r, q) we first zero the whole sum[p] vector.
// 2) Then we traverse s as the outer inner-loop index and p as the
//    innermost index:
//
//        for (s)
//          a_val = A[r][q][s];
//          for (p)
//            sum[p] += a_val * C4[s][p];
//
//    This ordering exploits row-major layout of C4 (p is innermost) and
//    gives contiguous access both to C4[s][p] and sum[p].
//    We still read each A[r][q][s] exactly once and only write A[r][q][p]
//    after all sums are finished, so we preserve the original semantics.
// ---------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// View of A where the last dimension is named 's' instead of 'p'.
	// This lets us naturally pair it with C4's 's' dimension in the
	// accumulation phase without changing the underlying layout.
	auto A_as_s = A ^ noarr::rename<'p', 's'>();

#pragma scop
	// Traverse all (r, q) pairs; A_as_s is the only structure that
	// actually carries these dimensions, but using traverser(A_as_s, C4, sum)
	// lets us use a single traversal interface.
	noarr::traverser(A_as_s, C4, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {

		// ------------------------------------------------------------------
		// 1) sum[p] = 0 for the current (r, q)
		// ------------------------------------------------------------------
		noarr::traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ------------------------------------------------------------------
		// 2) Accumulate sum[p] += A[r][q][s] * C4[s][p]
		//
		//    - trav_rq has 'r' and 'q' fixed; remaining dims are 's' (from
		//      A_as_s and C4) and 'p' (from C4 and sum).
		//    - We first fix 's', load the entire A[r][q][s] scalar once
		//      (as a_val), and then iterate over 'p' to update sum[p] using
		//      contiguous accesses to both sum and the C4 row at that 's'.
		// ------------------------------------------------------------------
		trav_rq.template for_dims<'s'>([&](auto trav_rqs) {
			// State now has indices (r, q, s) fixed.
			auto state_rqs = trav_rqs.state();

			// Load A[r][q][s] once; we keep it in a register while we sweep p.
			const num_t a_val = A_as_s[state_rqs];

			// Iterate over p as the innermost dimension for this (r, q, s).
			// trav_rqs.for_each will now only vary 'p'.
			trav_rqs.for_each([&](auto state_rqsp) {
				// state_rqsp carries (r, q, s, p); extra indices are safely
				// ignored by structures that do not have them.

				// sum[p] += A[r][q][s] * C4[s][p];
				sum[state_rqsp] += a_val * C4[state_rqsp];
			});
		});

		// ------------------------------------------------------------------
		// 3) Write back: A[r][q][p] = sum[p]
		//
		//    We now only need to loop over p, with r and q fixed by trav_rq.
		// ------------------------------------------------------------------
		trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
			auto state_rqp = trav_rqp.state();

			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

