// reorganizes the loops to:
//
//   for (r, q) {
//     sum[:] = 0;
//     for (s) {
//       a_rqs = A[r][q][s];
//       for (p)
//         sum[p] += a_rqs * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
