		auto state_rq = trav_rq.state();
		auto r_idx = get_index<'r'>(state_rq);
		auto q_idx = get_index<'q'>(state_rq);

		// View of A with r and q fixed: a 1D vector A_rq[p] == A[r][q][p]
		auto A_rq = A ^ fix<'r'>(r_idx) ^ fix<'q'>(q_idx);

		// ------------------------------------------------------------------
		// 1) Initialize the temporary sum[p] buffer for this (r, q) pair.
		// ------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ------------------------------------------------------------------
		// 2) Main computation:
		//      sum[p] += A[r][q][s] * C4[s][p]
		//    done as:
		//      for each s:
		//        a_rqs = A[r][q][s];           // scalar reused for all p
		//        for each p:
		//          sum[p] += a_rqs * C4[s][p];
		//
		//    Traversal order:
		//      - outer over 's' (rows of C4, and index into A_rq)
		//      - inner over 'p' (contiguous dimension of C4 and sum)
		// ------------------------------------------------------------------
		traverser(C4).template for_dims<'s'>([&](auto trav_s) {
			// Current row index s
			auto state_s = trav_s.state();
			auto s_idx = get_index<'s'>(state_s);

			// Load A[r][q][s] once and reuse for all p in this row
			num_t a_rqs = A_rq[noarr::idx<'p'>(s_idx)];

			// For the fixed s, iterate all p (inner-most, contiguous)
			trav_s.template for_dims<'p'>([&](auto trav_sp) {
				auto state_sp = trav_sp.state(); // contains 's' and 'p'

				// C4[s][p]
				num_t c_val = C4[state_sp];

				// sum has only dimension 'p'; the extra 's' index present
				// in state_sp is ignored when indexing sum.
				sum[state_sp] += a_rqs * c_val;
			});
		});

		// ------------------------------------------------------------------
		// 3) Write the computed sum[p] back to A[r][q][p].
		//    Here we again traverse over p only (1D).
		// ------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			A_rq[state_p] = sum[state_p];
		});
	});
#pragma endscop
}

