constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout   = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout  = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                 // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// Precompute lengths once; they are constant during the whole run.
	const auto np_len_A  = A  | get_length<'p'>();
	const auto np_len_C4 = C4 | get_length<'p'>();

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([&](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);

		A[state] = static_cast<num_t>(( (r * q + p) % np_len_A ))
			/ static_cast<num_t>(np_len_A);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([&](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);

		C4[state] = static_cast<num_t>(( (s * p) % np_len_C4 ))
			/ static_cast<num_t>(np_len_C4);
	});
}

// computation kernel
//
// Original C kernel:
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// Optimization strategy:
//
// - Work per (r,q) pair.
// - For each (r,q), we first zero the whole temporary vector sum[p].
// - Then we loop over s outermost, and for each s we:
//     * Load A[r][q][s] once.
//     * Traverse row C4[s][p] and update all sum[p].
//   This turns the kernel into a matrix–vector multiplication:
//
//     sum[p] = Σ_s A[r][q][s] * C4[s][p]
//
//   which improves data locality by reusing A[r][q][s] across all p
//   and walking rows of C4 contiguously.
// - Finally, we copy sum[p] back into A[r][q][p].
//
// The arithmetic result is identical up to floating‑point associativity:
// we still compute the same sum over s for each (r,q,p), only in a
// different (but mathematically equivalent) order.
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

#pragma scop
	// Outer traversal over r and q (one work unit per (r,q))
	traverser(A, C4, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {

		// Extract indices r and q once for this tile.
		auto state_rq = trav_rq.state();
		const auto r_idx = get_index<'r'>(state_rq);
		const auto q_idx = get_index<'q'>(state_rq);

		// ---------------------------------------------------------------------
		// 1) sum[p] = 0 for all p
		// ---------------------------------------------------------------------
		//
		// We iterate only over dimension 'p'. The traverser generated here
		// has 'p' fixed and ignores r,q,s for the sum bag (which only has 'p').
		trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
			sum[trav_rqp] = static_cast<num_t>(0);
		});

		// ---------------------------------------------------------------------
		// 2) Accumulate over s:
		//      sum[p] += A[r][q][s] * C4[s][p]
		//    with s outer and p inner.
		// ---------------------------------------------------------------------
		//
		// Dimension 's' comes from C4. After for_dims<'s'>, trav_rqs has
		// r,q,s fixed and leaves 'p' free.
		trav_rq.template for_dims<'s'>([&](auto trav_rqs) {
			auto state_rqs_s = trav_rqs.state();
			const auto s_idx = get_index<'s'>(state_rqs_s);

			// Load A[r][q][s] once and reuse it across all p for this s.
			const auto state_rqs_A = idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);
			const num_t a_rqs = A[state_rqs_A];

			// Iterate all p at this fixed (r,q,s).
			// state_rqsp has dimensions {r,q,s,p}; 's' is ignored for sum,
			// and r,q are ignored for both C4 and sum.
			trav_rqs.for_each([&](auto state_rqsp) {
				const num_t c4_val = C4[state_rqsp];
				sum[state_rqsp] += a_rqs * c4_val;
			});
		});

		// ---------------------------------------------------------------------
		// 3) Copy sum[p] back into A[r][q][p]
		// ---------------------------------------------------------------------
		//
		// Again, we iterate over p only. We build the full state (r,q,p) for A
		// while sum only uses p.
		trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
			auto state_p = trav_rqp.state();
			const auto p_idx = get_index<'p'>(state_p);

			const auto state_rqp_A = idx<'r', 'q', 'p'>(r_idx, q_idx, p_idx);
			A[state_rqp_A] = sum[trav_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
