//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// Mathematically, for each fixed (r,q):
//   A_new[r][q][p] = Σ_s A[r][q][s] * C4[s][p]
//
// The computation over (p,s) is a sum of independent products, so we are free
// to reorder the p/s loops as long as, for every (r,q,p), we accumulate over
// all s exactly once. Below we use the following equivalent ordering:
//
//   for (r,q) {
//     sum[:] = 0;                  // clear once
//     for (s) {
//       a_rqs = A[r][q][s];        // scalar, reused across p
//       for (p)
//         sum[p] += a_rqs * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// This improves locality for C4 because C4[s][p] is laid out with p as the
// innermost dimension, so the inner loop over p walks C4 rows contiguously.
// We also reuse A[r][q][s] across all p for a given s.
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Pre-construct traversers that are reused inside the (r,q) loops.
	auto sum_trav = traverser(sum); // 1D over 'p'
	auto C4_trav  = traverser(C4);  // 2D over 's','p'

#pragma scop
	// Outer traversal over r and q (A has dimensions 'r','q','p').
