	traverser(A).template for_dims<'r', 'q'>([&](auto trav_rq) {

		// Extract current (r,q) once and reuse them in inner loops.
		auto rq_state = trav_rq.state(); // contains indices 'r','q'
		auto r_idx = get_index<'r'>(rq_state);
		auto q_idx = get_index<'q'>(rq_state);

		// --------------------------------------------------------------------
		// 1) Clear the accumulation buffer: sum[p] = 0 for all p.
		//    This matches the original "for (p) sum[p] = 0;" but uses a
		//    single traversal of the sum structure.
		// --------------------------------------------------------------------
		sum_trav.for_each([&](auto p_state) {
			sum[p_state] = static_cast<num_t>(0);
		});

		// --------------------------------------------------------------------
		// 2) Main accumulation:
		//    for (s)
		//      a_rqs = A[r][q][s];
		//      for (p)
		//        sum[p] += a_rqs * C4[s][p];
		//
		// We traverse C4 in 's'-major, 'p'-minor order. For each fixed 's'
		// we load A[r][q][s] once into a scalar and then walk along 'p',
		// which is the innermost (contiguous) dimension of C4.
		// --------------------------------------------------------------------
		C4_trav.template for_dims<'s'>([&](auto trav_s) {
			// trav_s has 's' fixed, remaining dimension is 'p'
			auto s_state = trav_s.state();      // contains index 's'
